package com.talentsync.gateway.config;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.cloud.gateway.filter.*; import org.springframework.core.Ordered; import org.springframework.http.*; import org.springframework.stereotype.Component; import org.springframework.web.server.ServerWebExchange; import reactor.core.publisher.Mono; import java.nio.charset.StandardCharsets; import java.util.*;
@Component public class JwtGatewayFilter implements GlobalFilter, Ordered { @Value("${jwt.secret}") String secret; private static final Set<String> PUBLIC=Set.of("/api/auth/login","/api/auth/register/candidate","/api/auth/register/recruiter"); public int getOrder(){return -1;} public Mono<Void> filter(ServerWebExchange e,GatewayFilterChain chain){String path=e.getRequest().getPath().value(); boolean publicGet=e.getRequest().getMethod()==HttpMethod.GET&&(path.equals("/api/jobs")||path.startsWith("/api/jobs/search")||path.matches("/api/jobs/\\d+")); if(PUBLIC.contains(path)||publicGet)return chain.filter(e); String h=e.getRequest().getHeaders().getFirst(HttpHeaders.AUTHORIZATION);if(h==null||!h.startsWith("Bearer "))return reject(e); try{Claims c=Jwts.parserBuilder().setSigningKey(Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8))).build().parseClaimsJws(h.substring(7)).getBody(); ServerWebExchange changed=e.mutate().request(e.getRequest().mutate().header("X-User-Id",String.valueOf(c.get("userId"))).header("X-User-Role",c.get("role",String.class)).build()).build();return chain.filter(changed);}catch(Exception ex){return reject(e);}} private Mono<Void> reject(ServerWebExchange e){e.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);return e.getResponse().setComplete();}}
